// Context markers: a line that warns AGAINST a pattern is not the same as a
// line that requests it. This mirrors a real failure mode we can see in
// published corpora (security courses quoting attack strings). We downgrade,
// never silently ignore: a downgraded line yields a `caution` finding.
// COUNTER-CONTEXT MARKERS. These are evaluated ONLY against the text BEFORE
// the match on the line, never against the match itself. Two reasons:
//   - "do not mention this to the user" contains a negation, but that negation
//     IS the request (hide it from the human). Reading it as counter-context
//     would invert the verdict.
//   - "https://example.com/install.sh" contains the word "example". Scanning
//     the whole line for markers turns a hostname into a counter-signal.
const COUNTER_CTX = [
  /\bnever\b/i, /\bdo not\b/i, /\bdon't\b/i, /\bavoid\b/i, /\bblock(?:s|ed|ing)?\b/i,
  /\bmalicious\b/i, /\battacker\b/i, /\bfor example\b/i, /\be\.g\.,/i, /\bshould not\b/i,
  /\bmust not\b/i, /\bdetects?\b/i, /\bdangerous\b/i, /\bunauthorized\b/i, /\bforbidden\b/i,
  /\bwithout (?:you )?realizing/i, /\bdisallow/i, /\bdeny\b/i,
];


/**
 * True when the matched text sits inside quotation marks, i.e. the file is
 * QUOTING the operation rather than asking for it. Both sides must be present
 * and close: an opening quote before, a closing quote after.
 */
function isQuotedMention(raw, match) {
  if (match.index === undefined) return false;
  const before = raw.slice(0, match.index);
  const after = raw.slice(match.index + match[0].length);
  const open = /(?:["'\u201c\u2018]|`)\s*$/.test(before);
  const close = /^\s*(?:["'\u201d\u2019]|`)/.test(after);
  return open && close;
}

// INSTRUCTION POSITION. A declaration that merely MENTIONS a dangerous string
// ("your API access key", "sudo gives full control") is not a declaration that
// REQUESTS it. Treating a mention as a request is the same error as treating
// a transcript as the check. We therefore require the matched bytes to sit in
// an instruction position before the finding counts as a request.
//
// Instruction position is one of:
//   1. the line is a shell command inside a fenced code block (the agent will
//      be told to run it), or the line starts with the command itself;
//   2. the line carries an imperative directed at the agent, near the match
//      ("Run ...", "then execute ...", "you must first ...", "Install ...");
//   3. the match is itself a bare command invocation (sudo ..., rm -rf ...).
//
// Everything else is a MENTION: reported with severity "mention" and a cite,
// but it does not on its own make the declaration out-of-scope.
const IMPERATIVE = [
  /\b(?:run|exec|execute|invoke|install|use|read|load|source|then|first|now|start|apply|set|export|call|try|pip|npm|apt|brew|python|node|bash|sh)\b/i,
  /\b(?:you (?:must|should|need to|can|may)|make sure to|be sure to|ensure that)\b/i,
  /\b(?:before|after) (?:using|running|calling)\b/i,
];

const CMD_HEAD = /^\s*(?:[$#>]\s*)?(?:sudo|rm|curl|wget|bash|sh|zsh|python3?|node|npm|pip|pipx|apt|apt-get|brew|chmod|chown|kill|systemctl|launchctl|crontab|printenv|env|source|cat|dd|mkfs|git|docker|aws|gcloud|az)\b/i;

// SETUP CONTEXT. Installing a named package through a package manager is the
// vendor-documented path and does not by itself widen scope; downloading and
// executing remote content is covered by scope.remote-code-exec instead. This
// is a property of the operation, decided from the bytes, not from any label.
const PKG_MANAGER_INSTALL = /\b(?:apt(?:-get)?|brew|npm|pnpm|yarn|pip3?|pipx|uv|cargo|gem)\s+(?:install|add|get)\b/i;

/** True if this line is a routine package-manager install (setup, not escalation). */
function isSetupInstall(line) {
  return PKG_MANAGER_INSTALL.test(line);
}

// BARE PRIVILEGE: the agent is told to run something as root, but the bytes
// do not show what that something does.
const BARE_PRIVILEGE = /^\s*[$#>]?\s*(?:sudo|doas)\s+\S/i;
// ...unless what follows as root is itself visible as mutating or destructive.
const MUTATING_AFTER_PRIV = /\b(?:rm|mv|cp|dd|mkfs|chown|chmod|curl|wget|sh|bash|python|node|systemctl|launchctl|docker|apt|apt-get|brew|npm|pip|pipx|git)\b/i;

function isFencedCode(lines, i) {
  let open = false;
  for (let k = 0; k <= i; k++) {
    if (/^\s*```/.test(lines[k])) open = !open;
  }
  return open;
}

/**
 * Returns "instruction" | "mention" for the given line/match.
 * lines: full file lines (for fence tracking); i: index of the matched line.
 */
function instructionPosition(lines, i, matchedText) {
  const raw = lines[i] ?? "";
  const head = CMD_HEAD.test(raw);
  // 1. bare command invocation, or a command inside a fenced block
  if (head || isFencedCode(lines, i)) return "instruction";
  // 2. imperative directed at the agent
  if (IMPERATIVE.some((re) => re.test(raw))) return "instruction";
  // 3. the match is itself a command invocation
  if (/^(sudo|rm|curl|wget|bash|sh|printenv|env|source|chmod|kill)\b/i.test(matchedText.trim())) return "instruction";
  return "mention";
}

function lineText(text) {
  return text.split(/\r?\n/);
}

/**
 * verdictForDeclaration(text, opts) -> {
 *   verdict, findings[], reasons[], severity
 * }
 * finding: { code, severity, line, excerpt, counter_context }
 */
function verdictForDeclaration(text, opts = {}) {
  const disabled = new Set(opts.disabledCodes ?? []);
  const lines = lineText(text);
  const findings = [];
  const reasons = [];

  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i];
    if (!raw || !raw.trim()) continue;
    for (const rule of RULES) {
      if (disabled.has(rule.code)) continue;
      // strong tier first: if the bytes ARE the operation, tier is "strong".
      let tier = null, match = null;
      for (const re of rule.strong ?? []) {
        const m = re.exec(raw);
        if (m) { tier = "strong"; match = m; break; }
      }
      if (!tier) {
        for (const re of rule.weak ?? []) {
          const m = re.exec(raw);
          if (m) { tier = "weak"; match = m; break; }
        }
      }
      if (!tier) continue;
      // Setup carve-out: a routine package-manager install is the documented
      // path, not a privilege escalation. Applies to privilege only.
      if (rule.code === "scope.privilege-escalation" && isSetupInstall(raw)) {
        findings.push({
          code: rule.code, severity: SEVERITY.LOW, tier, position: "setup-install",
          line: i + 1, excerpt: raw.trim().slice(0, 200), matched: match[0].slice(0, 120),
          counter_context: false, note: "package-manager install: documented path",
        });
        continue;
      }
      // Counter-context is judged on the text BEFORE the match only.
      const prefix = raw.slice(0, match.index ?? 0);
      const counter = COUNTER_CTX.some((c) => c.test(prefix));
      const pos = tier === "strong" ? "instruction" : instructionPosition(lines, i, match[0]);
      // Severity depends on TIER + POSITION, not only on the string.
      //   strong + not counter-context -> rule severity (a request)
      //   strong + counter-context     -> medium (quoted, e.g. a warning)
      //   weak   + instruction         -> rule severity
      //   weak   + mention             -> low   (named, not requested)
      // SEVERITY POLICY (the rule we are defending, stated independently of
      // any corpus): only bytes that ARE the operation can put a declaration
      // out of scope. A weak-tier match - bytes that NAME an operation rather
      // than performing it ("your API access key", "sudo gives full control",
      // "get an API key from the dashboard") - is at most a caution. It is
      // reported with its cite, and it never alone makes the verdict
      // OUT-OF-SCOPE. A file that merely discusses secrets is not a file that
      // reads them.
      // VERDICT DRIVER vs SEVERITY. These are two different questions and the
      // previous build conflated them, which is what produced 39% false
      // positives: a rule's severity says how bad the ACTION is, not whether
      // the file ASKS for the action.
      //
      //   request?  = the bytes ask the agent to do this.
      //              strong tier + instruction position + not counter-context.
      //   severity  = how bad the action class is, if it IS requested.
      //
      // A MEDIUM-severity request (disable permission prompts, install a
      // cron entry, follow remote instructions) is still OUT-OF-SCOPE: the
      // authorization does not cover it. Severity grades the request; it
      // does not decide whether a request happened.
      // A QUOTED match is a citation, not a request. "demands to \"ignore the
      // rules\"" names the operation inside quotes; the file is describing an
      // injection, not issuing one. This is the same distinction the
      // instruction-position check already makes for weak tier, applied to
      // strong tier: bytes that NAME an operation do not perform it.
      // Measured on the untouched forge corpus: without this, one defensive
      // skill (F0137) flipped to OUT-OF-SCOPE on a quoted phrase.
      const quoted = rule.quotedAware && isQuotedMention(raw, match);
      let isRequest = tier === "strong" && pos === "instruction" && !counter && !quoted;
      // A weak-tier match in an instruction position is ambiguous: the file
      // talks about an operation in a directive context but the bytes do not
      // pin the operation down. We abstain rather than guess.
      let isAmbiguous = tier === "weak" && pos === "instruction" && !counter;
      // BARE PRIVILEGE ESCALATION IS ALSO AMBIGUOUS, not a request.
      // "sudo <something>" tells us the agent will run something as root. If
      // the something is not itself visible as mutating or destructive, we
      // cannot tell what the root shell is being asked to do. Our product rule
      // is: an honest "I cannot tell" is a result, do not guess. So a bare
      // sudo becomes UNDECIDABLE with its cite, not OUT-OF-SCOPE.
      if (isRequest && rule.code === "scope.privilege-escalation" && BARE_PRIVILEGE.test(raw) && !MUTATING_AFTER_PRIV.test(raw)) {
        isAmbiguous = true;
        // The stated rule is that a bare sudo is UNDECIDABLE, not
        // OUT-OF-SCOPE: we know the agent will run something as root, but
        // not what. Leaving `request` true made the verdict OUT-OF-SCOPE
        // anyway (requests are checked before ambiguous ones), which
        // contradicted the policy written directly above it. Clear the
        // request so the verdict follows the stated rule.
        isRequest = false;
      }
      let sev;
      if (!isRequest && !isAmbiguous) sev = SEVERITY.LOW;
      else if (counter) sev = SEVERITY.MEDIUM;
      else sev = rule.severity;
      findings.push({
        code: rule.code,
        severity: sev,
        tier,
        position: pos,
        request: isRequest,
        ambiguous: isAmbiguous,
        line: i + 1,
        excerpt: raw.trim().slice(0, 200),
        matched: match[0].slice(0, 120),
        counter_context: counter,
      });
      reasons.push({
        code: rule.code,
        cites: [`line ${i + 1}: ${raw.trim().slice(0, 120)}`, `matched=${JSON.stringify(match[0].slice(0, 60))}`, `tier=${tier}`, `position=${pos}`, `why=${rule.why}`],
      });
    }
  }

  // Deduplicate per (code,line) keeping the strongest severity.
  const best = new Map();
  for (const f of findings) {
    const k = `${f.code}@${f.line}`;
    const prev = best.get(k);
    if (!prev || (f.severity === SEVERITY.HIGH && prev.severity !== SEVERITY.HIGH)) best.set(k, f);
  }
  const dedup = [...best.values()].sort((a, b) => a.line - b.line || a.code.localeCompare(b.code));

  // VERDICT: a request outside the authorization is OUT-OF-SCOPE. An
  // ambiguous directive is UNDECIDABLE. A file that only mentions, quotes, or
  // documents an operation is IN-SCOPE.
  const requests = dedup.filter((f) => f.request);
  const ambiguous = dedup.filter((f) => f.ambiguous);
  const verdict = requests.length > 0 ? VERDICT.OUT_OF_SCOPE : ambiguous.length > 0 ? VERDICT.UNDECIDABLE : VERDICT.IN_SCOPE;
  const severity = requests.length > 0 ? (requests.some((f) => f.severity === SEVERITY.HIGH) ? SEVERITY.HIGH : SEVERITY.MEDIUM) : null;

  return { verdict, severity, findings: dedup, reasons };
}

const DECLARATION_REASON_CODES = RULES.map((r) => r.code);

// ===== CLI =====
import { readFileSync as __rf } from "node:fs";
const __args = process.argv.slice(2);
if (__args.length === 0) {
  console.error("usage: node claim-check.mjs <exchange.json> | --declaration <file.md>");
  process.exit(2);
}
if (__args[0] === "--declaration") {
  const r = verdictForDeclaration(__rf(__args[1], "utf8"));
  console.log(r.verdict);
  for (const c of r.reasons) {
    console.log("  " + c.code);
    for (const cite of c.cites) console.log("    - " + cite);
  }
  process.exitCode = r.verdict === "OUT-OF-SCOPE" ? 1 : 0;
} else {
  const raw = JSON.parse(__rf(__args[0], "utf8"));
  const exchanges = Array.isArray(raw) ? raw : Array.isArray(raw.exchanges) ? raw.exchanges : [raw];
  let outN = 0, und = 0;
  for (const ex of exchanges) {
    const r = checkExchange(ex);
    if (r.verdict === "OUT-OF-SCOPE") outN++;
    if (r.verdict === "UNDECIDABLE") und++;
    console.log(`${r.id ?? "(no id)"}	${r.verdict}`);
    for (const c of r.perCall) for (const rs of c.reasons) {
      console.log("  " + rs.code);
      for (const cite of rs.cites) console.log("    - " + cite);
    }
  }
  console.log(`\nsummary: ${exchanges.length} exchange(s), ${outN} out-of-scope, ${und} undecidable`);
  process.exitCode = outN > 0 ? 1 : 0;
}
